#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1000000000;
const int MAXN = 2000;
const int dr[] = {0, -1, 0, 1};
const int dc[] = {1, 0, -1, 0};

int n, T, startR, startC;
int A[12][12], B[12][12], F[12][12];
vector<int> e[2000];
vector<int> things[12][12];
int leftCnt = 0, rightCnt = 0;

int pairU[MAXN + 1], pairV[MAXN + 1], distHK[MAXN + 1];

bool bfsHK() {
    queue<int> q;
    for (int u = 1; u <= leftCnt; ++u) {
        if (pairU[u] == 0) {
            distHK[u] = 0;
            q.push(u);
        } else {
            distHK[u] = INF;
        }
    }
    distHK[0] = INF;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (distHK[u] < distHK[0]) {
            for (int i = 0; i < (int)e[u - 1].size(); ++i) {
                int v = e[u - 1][i] + 1;
                if (distHK[pairV[v]] == INF) {
                    distHK[pairV[v]] = distHK[u] + 1;
                    q.push(pairV[v]);
                }
            }
        }
    }
    return distHK[0] != INF;
}

bool dfsHK(int u) {
    if (u == 0) return true;
    for (int i = 0; i < (int)e[u - 1].size(); ++i) {
        int v = e[u - 1][i] + 1;
        if (distHK[pairV[v]] == distHK[u] + 1) {
            if (dfsHK(pairV[v])) {
                pairV[v] = u;
                pairU[u] = v;
                return true;
            }
        }
    }
    distHK[u] = INF;
    return false;
}

int hopcroftKarp() {
    for (int i = 0; i <= leftCnt; ++i) pairU[i] = 0;
    for (int i = 0; i <= rightCnt; ++i) pairV[i] = 0;
    int ans = 0;
    while (bfsHK()) {
        for (int u = 1; u <= leftCnt; ++u) {
            if (pairU[u] == 0 && dfsHK(u)) ++ans;
        }
    }
    return ans;
}

void bfsFromStart(int sr, int sc) {
    queue<int> qr, qc;
    memset(F, 255, sizeof(F));
    qr.push(sr);
    qc.push(sc);
    F[sr][sc] = 0;
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c = qc.front(); qc.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (A[nr][nc] >= 0 && F[nr][nc] < 0) {
                F[nr][nc] = F[r][c] + 1;
                qr.push(nr);
                qc.push(nc);
            }
        }
    }
}

void addMonsterEdges(int sr, int sc, int cnt) {
    int seen[12][12];
    queue<int> qr, qc;
    memset(seen, 255, sizeof(seen));
    qr.push(sr);
    qc.push(sc);
    seen[sr][sc] = 0;
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c = qc.front(); qc.pop();
        int lim = min(T, F[r][c]);
        if (seen[r][c] > lim) continue;
        for (int i = 0; i < (int)things[r][c].size(); ++i)
            for (int k = 0; k < cnt; ++k)
                e[leftCnt + k].push_back(things[r][c][i]);
        if (seen[r][c] == lim) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (A[nr][nc] >= 0 && seen[nr][nc] < 0) {
                seen[nr][nc] = seen[r][c] + 1;
                qr.push(nr);
                qc.push(nc);
            }
        }
    }
    leftCnt += cnt;
}

int main() {
    scanf("%d%d", &n, &T);
    memset(A, 255, sizeof(A));
    memset(B, 255, sizeof(B));
    for (int i = 1; i <= n; ++i) {
        while (getchar() != '\n');
        for (int j = 1; j <= n; ++j) {
            int ch = getchar();
            if (ch >= '0' && ch <= '9') A[i][j] = ch - '0';
            if (ch == 'Z') {
                startR = i;
                startC = j;
            }
        }
    }
    bfsFromStart(startR, startC);
    while (getchar() != '\n');
    for (int i = 1; i <= n; ++i) {
        while (getchar() != '\n');
        for (int j = 1; j <= n; ++j) {
            int ch = getchar();
            if (ch >= '0' && ch <= '9') B[i][j] = ch - '0';
            for (int k = 0; k < B[i][j]; ++k)
                things[i][j].push_back(rightCnt++);
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (F[i][j] < 0) F[i][j] = INF;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (A[i][j] > 0) addMonsterEdges(i, j, A[i][j]);
    printf("%d\n", hopcroftKarp());
    return 0;
}
